#!/usr/bin/env python3
"""One targeted regression: generated bytecode and plot-only additions never change source identity."""
import json
from pathlib import Path
from run_pilot import ROOT,freeze

def main():
    manifest=ROOT/'data/CAMPAIGN.json'
    before=freeze(ROOT,manifest)
    fixture_root=ROOT/'vendor/rec_hheli/vendor/baseline'
    fixtures=[fixture_root/'__pycache__/compact33_stage1_cache_fixture.pyc',
              fixture_root/'compact33_stage1_cache_fixture.pyo',
              ROOT/'code/plotting.py']
    created=[]
    try:
        for path in fixtures:
            path.parent.mkdir(parents=True,exist_ok=True)
            with path.open('xb') as f:f.write(b'temporary non-source cache fixture\n')
            created.append(path)
        during=freeze(ROOT,manifest)
        assert before['files']==during['files']
        assert before['base_identity']==during['base_identity']
        assert not any('__pycache__' in Path(p).parts or Path(p).suffix in ('.pyc','.pyo') for p in during['files'])
    finally:
        for path in created:path.unlink(missing_ok=True)
    after=freeze(ROOT,manifest)
    assert before==after
    result={'status':'PASS','check':'freeze files and base invariant under cache and plotting.py presence/absence',
            'fixture_paths':[str(p.relative_to(ROOT)) for p in fixtures],
            'fixtures_cleaned':all(not p.exists() for p in fixtures),'source_file_count':len(before['files']),
            'base_identity':before['base_identity']}
    (ROOT/'evidence/FREEZE_CACHE_VERIFICATION.json').write_text(json.dumps(result,indent=2)+'\n')
    print(json.dumps(result,indent=2))

if __name__=='__main__':main()
